/* @autogenerated */
package net.civeira.phylax.feature.observe.config;

import java.util.Optional;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.ObservabilityConfig;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.gateway.ObservabilityConfigFilter;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.gateway.ObservabilityConfigQueryRepositoryGateway;

/**
 * Snapshot of the global configuration (observability-config, row {@code default}) for the
 * collector. As with the sources, the reads never touch the database (they are called from the
 * ingestion): the snapshot is reloaded in the background at startup, every minute and shortly after
 * the row changes. Without the row, the defaults of config/observability.yaml are used.
 */
@ApplicationScoped
@RequiredArgsConstructor
@Slf4j
public class ObservabilitySettings {

  public static final String CODE = "default";
  private static final long PERIOD_SECONDS = 60;

  private final ObservabilityConfigQueryRepositoryGateway configs;
  private final ObserveDefaults defaults;

  private volatile ObserveSettings current;
  private final AtomicBoolean pending = new AtomicBoolean();
  private final AtomicBoolean started = new AtomicBoolean();
  private final ScheduledExecutorService reloader =
      Executors.newSingleThreadScheduledExecutor(r -> {
        Thread thread = new Thread(r, "observe-settings");
        thread.setDaemon(true);
        return thread;
      });

  /** The current configuration (the defaults until the first load). */
  public ObserveSettings current() {
    ObserveSettings value = current;
    return null == value ? defaults.settings() : value;
  }

  /** Loads now and then every minute. Called at startup, outside any log call. */
  public void start() {
    reload();
    if (started.compareAndSet(false, true)) {
      reloader.scheduleWithFixedDelay(this::reloadQuietly, PERIOD_SECONDS, PERIOD_SECONDS,
          TimeUnit.SECONDS);
    }
  }

  public void stop() {
    reloader.shutdownNow();
  }

  /** Reloads in the background shortly after a change (once the transaction has committed). */
  public void invalidate() {
    if (pending.compareAndSet(false, true)) {
      reloader.schedule(() -> {
        pending.set(false);
        reloadQuietly();
      }, 1, TimeUnit.SECONDS);
    }
  }

  /** Reads the row; only from the startup or the background thread. */
  public synchronized void reload() {
    Optional<ObservabilityConfig> row =
        configs.find(ObservabilityConfigFilter.builder().code(CODE).build());
    if (row.isEmpty() && null == current) {
      log.warn(
          "observability-config has no row '{}': using the defaults of config/observability.yaml",
          CODE);
    }
    current = row.map(this::toSettings).orElseGet(defaults::settings);
  }

  private void reloadQuietly() {
    try {
      reload();
    } catch (RuntimeException ex) {
      log.warn("Unable to reload the observability configuration: {}", ex.getMessage());
    }
  }

  private ObserveSettings toSettings(final ObservabilityConfig row) {
    return new ObserveSettings(
        positive(row.getRetentionDaysLogs(), defaults.getRetentionDaysLogs()),
        positive(row.getRetentionDaysTraces(), defaults.getRetentionDaysTraces()),
        positive(row.getRetentionDaysErrors(), defaults.getRetentionDaysErrors()),
        positive(row.getRetentionDaysMetrics(), defaults.getRetentionDaysMetrics()),
        positive(row.getRetentionDaysMetricsRollup(), defaults.getRetentionDaysMetricsRollup()),
        positive(row.getMaxDiskMb(), defaults.getMaxDiskMb()),
        ObserveSettings.keys(row.getScrubFields().orElse(defaults.getScrubFields())),
        ObserveSettings.keys(row.getLabelDenylist().orElse(defaults.getLabelDenylist())),
        Boolean.TRUE.equals(row.isCaptureRequestBody()));
  }

  /** The generated DAOs read a NULL integer as 0: a value not set is the default. */
  private static int positive(final Integer value, final int defaultValue) {
    return null == value || value <= 0 ? defaultValue : value;
  }
}
